from decimal import Decimal


def parse_number(text: str) -> Decimal:
    if not isinstance(text, str):
        raise ValueError("invalid number")
    s = text.strip(" \t\u00a0")
    if not s:
        raise ValueError("invalid number")
    negative = False
    if "(" in s or ")" in s:
        if len(s) < 2 or s[0] != "(" or s[-1] != ")":
            raise ValueError("invalid number")
        inner = s[1:-1]
        if "(" in inner or ")" in inner:
            raise ValueError("invalid number")
        if "+" in inner or "-" in inner:
            raise ValueError("invalid number")
        negative = True
        s = inner
    else:
        if s[0] in "+-":
            negative = s[0] == "-"
            s = s[1:]
            if "+" in s or "-" in s:
                raise ValueError("invalid number")
        elif "+" in s or "-" in s:
            raise ValueError("invalid number")
    t = s.replace(" ", "").replace("\u00a0", "")
    if not t:
        raise ValueError("invalid number")
    for ch in t:
        if ch not in "0123456789.,":
            raise ValueError("invalid number")
    if not any(ch in "0123456789" for ch in t):
        raise ValueError("invalid number")
    has_dot = "." in t
    has_comma = "," in t
    if has_dot and has_comma:
        if t.rfind(".") > t.rfind(","):
            decimal_sep = "."
            thousands_sep = ","
        else:
            decimal_sep = ","
            thousands_sep = "."
        if t.count(decimal_sep) != 1:
            raise ValueError("invalid number")
        int_part, dec_part = t.split(decimal_sep)
        if not int_part or not dec_part:
            raise ValueError("invalid number")
        if not all(ch in "0123456789" for ch in dec_part):
            raise ValueError("invalid number")
        if thousands_sep not in int_part:
            raise ValueError("invalid number")
        groups = int_part.split(thousands_sep)
        if not (1 <= len(groups[0]) <= 3) or any(len(g) != 3 for g in groups[1:]):
            raise ValueError("invalid number")
        if not all(g and all(ch in "0123456789" for ch in g) for g in groups):
            raise ValueError("invalid number")
        normalized = "".join(groups) + "." + dec_part
    elif has_comma:
        if t.count(",") > 1:
            groups = t.split(",")
            if not (1 <= len(groups[0]) <= 3) or any(len(g) != 3 for g in groups[1:]):
                raise ValueError("invalid number")
            normalized = "".join(groups)
        else:
            int_part, dec_part = t.split(",")
            if not int_part or not dec_part:
                raise ValueError("invalid number")
            normalized = int_part + "." + dec_part
    elif has_dot:
        if t.count(".") > 1:
            groups = t.split(".")
            if not (1 <= len(groups[0]) <= 3) or any(len(g) != 3 for g in groups[1:]):
                raise ValueError("invalid number")
            normalized = "".join(groups)
        else:
            int_part, dec_part = t.split(".")
            if not int_part or not dec_part:
                raise ValueError("invalid number")
            normalized = int_part + "." + dec_part
    else:
        normalized = t
    return Decimal(("-" if negative else "") + normalized)
